&lt;style&gt;span.Cat&#233;gorie { display:none; }&lt;/style&gt;&lt;div class=&quot;presentation navmenu&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Acc&#232;s rapide aux sections sur l&#39;&#233;quipement&lt;a class=&quot;headeranchor&quot; id=&quot;Acc&#232;s_rapide_aux_sections_sur_l&#233;quipement_0&quot; href=&quot;#Acc&#232;s_rapide_aux_sections_sur_l&#233;quipement_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table&gt;&lt;tr style=&quot;vertical-align: top; text-align: left&quot;&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes.html&quot; title=&quot;Tableau r&#233;capitulatif des armes&quot;&gt;Les armes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armes.html&quot; title=&quot;Descriptions individuelles des armes&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes-&#192;-Feu.html&quot; title=&quot;Tableau r&#233;capitulatif des armes &#224; feu&quot;&gt;Les armes &#224; feu&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armes-&#192;-Feu.html&quot; title=&quot;Descriptions individuelles des armes &#224; feu&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures.html&quot; title=&quot;Tableau r&#233;capitulatif des armures&quot;&gt;Les armures&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armures.html&quot; title=&quot;Descriptions individuelles des armures&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures.html&quot; title=&quot;Caract&#233;ristiques des armures&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;Les mat&#233;riaux sp&#233;ciaux&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animaux,%20montures%20et%20leur%20%C3%A9quipement.ashx#&quot; title=&quot;Animaux, montures et leur &#233;quipement&quot;&gt;Animaux, montures et leur &#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chroniques-Des-&#201;claireurs.html&quot; title=&quot;Chroniques des Explorateurs&quot;&gt;Chroniques des Explorateurs&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;%C3%89quipement%20daventurier.ashx#&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;&#201;quipement d&#39;aventurier&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Focalisateurs%20de%20canalisation.ashx#&quot; title=&quot;Focalisateurs de canalisation&quot;&gt;Focalisateurs de canalisation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H%C3%A9bergement%20et%20services.ashx#&quot; title=&quot;H&#233;bergement et services&quot;&gt;H&#233;bergement et services&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Jeux.ashx#&quot; title=&quot;Jeux&quot;&gt;Jeux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;March%C3%A9%20noir.ashx#&quot; title=&quot;March&#233; noir&quot;&gt;March&#233; noir&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moyens%20de%20transport.ashx#&quot; title=&quot;Moyens de transport&quot;&gt;Moyens de transport&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nourriture%20et%20Boissons.ashx#&quot; title=&quot;Nourriture et Boissons&quot;&gt;Nourriture et Boissons&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Outils%20de%20comp%C3%A9tences.ashx#&quot; title=&quot;Outils de comp&#233;tences&quot;&gt;Outils de comp&#233;tences&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trousses%20d%C3%A9quipement.ashx#&quot; title=&quot;Trousses d&amp;#39;&#233;quipement&quot;&gt;Trousses d&#39;&#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;V%C3%AAtements.ashx#&quot; title=&quot;V&#234;tements&quot;&gt;V&#234;tements&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.ashx#&quot; title=&quot;Les poisons  &quot;&gt;Poisons&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes%20alchimiques.ashx#&quot; title=&quot;Armes alchimiques&quot;&gt;Armes alchimiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Outils%20alchimiques.ashx#&quot; title=&quot;Outils alchimiques&quot;&gt;Outils alchimiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rem%C3%A8des%20alchimiques.ashx#&quot; title=&quot;Rem&#232;des alchimiques&quot;&gt;Rem&#232;des alchimiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Argent-Et-Richesse.html&quot; title=&quot;Argent et richesse&quot;&gt;L&#39;argent et la richesse&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchandises.html&quot; title=&quot;Marchandises&quot;&gt;Les marchandises&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poids-Transportable.html&quot; title=&quot;Poids transportable&quot;&gt;Le poids transportable&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;actifs-Alchimiques.html&quot; title=&quot;R&#233;actifs alchimiques&quot;&gt;Les r&#233;actifs alchimiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;&lt;i&gt;Les armures d&#233;crites ci-dessous sont celles pr&#233;sent&#233;es dans le &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures.html&quot; title=&quot;Tableau r&#233;capitulatif des armures&quot;&gt;tableau r&#233;capitulatif des armures&lt;/a&gt;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Armures l&#233;g&#232;res&lt;a class=&quot;headeranchor&quot; id=&quot;Armures_l&#233;g&#232;res_0&quot; href=&quot;#Armures_l&#233;g&#232;res_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure c&#233;r&#233;monielle de soie&quot; href=&quot;#Armure c&#233;r&#233;monielle de soie&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure c&#233;r&#233;monielle de soie*.&lt;/b&gt; Port&#233;es lors des c&#233;r&#233;monies ou par-dessus une armure plus lourde (sans apporter d’avantage), ces robes se composent de plusieurs &#233;paisseurs de tissu et d’une couche ext&#233;rieure de soie brod&#233;e de brocarts d’or et couverte de clous en m&#233;tal.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure de bois&quot; href=&quot;#Armure de bois&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure de bois.&lt;/b&gt; Cette armure en cuir est pourvue de plaques de bois ignifug&#233;es cousues au niveau des zones vitales. Bien qu’elle ne soit pas aussi efficace qu’une armure en m&#233;tal, elle offre une meilleure protection que le cuir seul. Contrairement aux armures de m&#233;tal, la flottabilit&#233; du bois r&#233;duit le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Malusarmure.html&quot; title=&quot;malus d&amp;#39;armure&quot;&gt;malus d’armure&lt;/a&gt; pour &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;nager&lt;/a&gt; &#224; 0.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure de cuir&quot; href=&quot;#Armure de cuir&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure de cuir.&lt;/b&gt; L’armure de cuir se compose de plusieurs pi&#232;ces de cuir superpos&#233;es, bouillies pour augmenter leur r&#233;sistance naturelle puis cousues ensemble. Bien qu’elle ne soit pas aussi solide qu’une armure de m&#233;tal, la flexibilit&#233; qu’elle donne &#224; son porteur en fait l’un des types d’armure les plus utilis&#233;s.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure de cuir clout&#233;e&quot; href=&quot;#Armure de cuir clout&#233;e&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure de cuir clout&#233;e.&lt;/b&gt; Version am&#233;lior&#233;e de l’&lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-(Armure).html&quot; title=&quot;Armure de cuir&quot;&gt;armure de cuir&lt;/a&gt;, l’armure de cuir clout&#233;e est couverte de dizaines de protub&#233;rances m&#233;talliques. Si, individuellement, ces clous ronds n’offrent que peu de protection, leur nombre permet d’arr&#234;ter les tranchants l&#233;taux et de les &#233;loigner des points vitaux. La rigidit&#233; du m&#233;tal ajout&#233; donne cependant moins de mobilit&#233; qu’une armure de cuir normale.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.La Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea World Guide/La Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISWG.gif&quot; style=&quot;opacity: 0.7&quot;/&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure de feuilles&quot; href=&quot;#Armure de feuilles&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure de feuilles.&lt;/b&gt; Les &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druides&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;elfiques&lt;/a&gt; utilisent des composants alchimiques secrets pour traiter des feuilles particuli&#232;res et en faire des armures pour leurs guerriers. Ce sont toujours des objets &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure de parade&quot; href=&quot;#Armure de parade&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure de parade.&lt;/b&gt; Les pays les plus riches ayant des arm&#233;es permanentes ont un uniforme diff&#233;rent pour les &#233;v&#232;nements pacifiques ostentatoires tels que les parades, les c&#233;r&#233;monies de couronnement, etc. L’apparence de cette armure diff&#232;re en fonction du pays d’origine et de la branche militaire impliqu&#233;e mais elle offre quand m&#234;me une certaine protection au cas o&#249; le soldat devrait se battre en tenue de parade. Par exemple, l’armure de parade d’un pays peut se composer d’une chemise de mailles, d’un tabard, de jambi&#232;res de cuir et d’un casque ail&#233;. Si le personnage porte une armure de parade, il gagne un bonus de circonstances de +2 &#224; ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; pour influencer une personne de son pays. En fonction du pays, l’armure de parade peut &#234;tre faite en cuir, en m&#233;tal ou combiner les deux.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure en bois de rose&quot; href=&quot;#Armure en bois de rose&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure en bois de rose.&lt;/b&gt; Cette armure de cuir est envelopp&#233;e dans du lierre de rose sp&#233;cial. Elle est consid&#233;r&#233;e comme une &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Cuir-(Armure).html&quot; title=&quot;Armure de cuir&quot;&gt;armure de cuir&lt;/a&gt; avec des &lt;a class=&quot;pagelink&quot; href=&quot;Pointes-Darmure-(Armure).html&quot; title=&quot;Pointes d&amp;#39;armure&quot;&gt;pointes d’armure&lt;/a&gt;. Les lierres doivent &#234;tre arros&#233;s avec au moins 3,7 litres d’eau chaque jour sous peine de f&#226;ner et mourir, transformant l’armure en une armure de cuir classique.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure lamellaire en cuir&quot; href=&quot;#Armure lamellaire en cuir&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure lamellaire en cuir*.&lt;/b&gt; L’armure lamellaire est un type d’armure constitu&#233; de petites plaques de diff&#233;rents m&#233;taux qui sont fix&#233;es en rang&#233;es parall&#232;les par une fine corde. Les plaques lamellaires peuvent &#234;tre faites de cuir laqu&#233;, de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Corne-(Armure).html&quot; title=&quot;Armure lamellaire en corne&quot;&gt;corne&lt;/a&gt;, voire m&#234;me de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Pierre-(Armure).html&quot; title=&quot;Armure lamellaire en pierre&quot;&gt;pierre&lt;/a&gt;, mais les armures de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Fer-(Armure).html&quot; title=&quot;Armure lamellaire en fer&quot;&gt;fer&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Acier-(Armure).html&quot; title=&quot;Armure lamellaire en acier&quot;&gt;acier&lt;/a&gt; sont les plus courantes. L’armure lamellaire peut &#234;tre fa&#231;onn&#233;e en diff&#233;rentes formes, y compris en pi&#232;ces isol&#233;es telles que des cuirasses, des jambi&#232;res ou m&#234;me des vestes compl&#232;tes. Les propri&#233;t&#233;s des combinaisons et des pi&#232;ces sp&#233;cifiques de l’armure lamellaire sont d&#233;finies par leur mat&#233;riau.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure matelass&#233;e&quot; href=&quot;#Armure matelass&#233;e&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure matelass&#233;e.&lt;/b&gt; Plus qu’un simple v&#234;tement, l’armure matelass&#233;e m&#234;le de lourdes couches de tissus &#233;pais &#224; un rembourrage tr&#232;s dense, pour cr&#233;er une protection basique et bon march&#233; que porte g&#233;n&#233;ralement les gens qui ne pr&#233;voient pas de se lancer dans des combats mortels ou qui cherchent &#224; conserver un maximum d’aisance.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Chemise de mailles&quot; href=&quot;#Chemise de mailles&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Chemise de mailles.&lt;/b&gt; Couvrant le torse, cette chemise est compos&#233;e de milliers d’anneaux de m&#233;tal entrecrois&#233;s.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cuirasse lamellaire&quot; href=&quot;#Cuirasse lamellaire&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cuirasse lamellaire*.&lt;/b&gt; Cette armure se compose d’une cuirasse l&#233;g&#232;re et d’&#233;pauli&#232;res faites de plaques de cuir laqu&#233; fix&#233;es et assembl&#233;es sur une chemise en soie.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Haramaki&quot; href=&quot;#Haramaki&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Haramaki*.&lt;/b&gt; Aussi appel&#233; chauffe-nombril, le haramaki est une simple ceinture large en soie bord&#233;e de mailles ou articul&#233;e de plaques de m&#233;tal et nou&#233;e sur l’estomac pour le prot&#233;ger.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Kilt renforc&#233;&quot; href=&quot;#Kilt renforc&#233;&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Kilt renforc&#233;.&lt;/b&gt; Lorsque le personnage ajoute un kilt renforc&#233; &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Legeres.html&quot; title=&quot;armure l&#233;g&#232;re&quot;&gt;armure l&#233;g&#232;re&lt;/a&gt;, l’ensemble est consid&#233;r&#233; comme une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Intermediaires.html&quot; title=&quot;armure interm&#233;diaire&quot;&gt;armure interm&#233;diaire&lt;/a&gt;. De m&#234;me, un kilt et une armure interm&#233;diaire sont consid&#233;r&#233;s comme une &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Lourdes.html&quot; title=&quot;armure lourde&quot;&gt;armure lourde&lt;/a&gt;. Ajouter un kilt renforc&#233; &#224; une armure lourde n’a aucun effet.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;V&#234;tements rembourr&#233;s&quot; href=&quot;#V&#234;tements rembourr&#233;s&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;V&#234;tements rembourr&#233;s.&lt;/b&gt; Cette version am&#233;lior&#233;e de l’&lt;a class=&quot;pagelink&quot; href=&quot;Armure-Matelass&#233;e-(Armure).html&quot; title=&quot;Armure matelass&#233;e&quot;&gt;armure matelass&#233;e&lt;/a&gt; est constitu&#233;e de couches internes sp&#233;cifiquement con&#231;ues pour pi&#233;ger les &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;ches-(Arme).html&quot; title=&quot;Fl&#232;ches (20)&quot;&gt;fl&#232;ches&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Carreaux-Darbal&#232;te-(Arme).html&quot; title=&quot;Carreaux d&amp;#39;arbal&#232;te (10)&quot;&gt;carreaux&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;chette-(Arme).html&quot; title=&quot;Fl&#233;chette&quot;&gt;fl&#233;chettes&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Shurikens-(Arme).html&quot; title=&quot;Shurikens (5)&quot;&gt;shurikens&lt;/a&gt;, les &lt;a class=&quot;pagelink&quot; href=&quot;Dague-(Arme).html&quot; title=&quot;Dague&quot;&gt;dagues&lt;/a&gt; de jet et autres petites armes &#224; distance perforantes. Lorsque l’une de ces armes frappe le personnage, elle se fiche dans les &#233;paisseurs et n’arrive pas &#224; le blesser. Le v&#234;tement rembourr&#233; donne au personnage une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 3/— contre les attaques de ce genre. Les couches sp&#233;ciales de l’armure n’ont aucun effet sur les autres types d’armes.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Armures interm&#233;diaires&lt;a class=&quot;headeranchor&quot; id=&quot;Armures_interm&#233;diaires_1&quot; href=&quot;#Armures_interm&#233;diaires_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure &#224; quatre miroirs&quot; href=&quot;#Armure &#224; quatre miroirs&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure &#224; quatre miroirs*.&lt;/b&gt; Cette armure se compose de quatre plaques fix&#233;es par des bandouli&#232;res de cuir. Deux plaques rondes prot&#232;gent le devant et l’arri&#232;re, tandis que deux plaques rectangulaires, plus petites, couvrent les flancs. L’armure &#224; quatre miroirs se porte par-dessus une chemise de mailles pour offrir plus de protection. Elle est fournie avec un casque &#224; pointes avec un capuchon en mailles.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure de la montagne&quot; href=&quot;#Armure de la montagne&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure de la montagne*.&lt;/b&gt; Cette armure interm&#233;diaire se compose de centaines de petites pi&#232;ces d’acier entrecrois&#233;es dispos&#233;es de mani&#232;re &#224; former l’ancien symbole du terme &#171; montagne &#187;. Les mailles sont ensuite riv&#233;es &#224; une armature en tissu ou en cuir. L’armure se porte comme une &lt;a class=&quot;pagelink&quot; href=&quot;Cotte-De-Mailles-(Armure).html&quot; title=&quot;Cotte de mailles&quot;&gt;cotte de mailles&lt;/a&gt; et couvre le torse, les &#233;paules et les cuisses.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure d&#233;cailles&quot; href=&quot;#Armure d&#233;cailles&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure d&#39;&#233;cailles.&lt;/b&gt; L’armure d’&#233;cailles se compose de dizaines de petites pi&#232;ces de m&#233;tal superpos&#233;es. Semblable au &lt;a class=&quot;pagelink&quot; href=&quot;Clibanion-(Armure).html&quot; title=&quot;Clibanion&quot;&gt;clibanion&lt;/a&gt; et &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Crevice-(Armure).html&quot; title=&quot;Crevice&quot;&gt;crevice&lt;/a&gt;, l’armure d’&#233;cailles se caract&#233;rise par la disposition flexible de ses &#233;cailles quine g&#234;ne pas la mobilit&#233; du porteur, aux d&#233;pends des couches de protection suppl&#233;mentaires de l’armure. L’armure d’&#233;cailles inclut des &lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-(Arme).html&quot; title=&quot;Gantelet&quot;&gt;gantelets&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure en peau&quot; href=&quot;#Armure en peau&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure en peau.&lt;/b&gt; L’armure en peau est faite avec le cuir tann&#233; de b&#234;tes &#224; la peau  particuli&#232;rement &#233;paisse, cousu avec de multiples couches superpos&#233;es de cuir brut ou des pi&#232;ces ext&#233;rieures de cuir matelass&#233; ou rembourr&#233; de fourrure. Les d&#233;g&#226;ts faits &#224; l’armure se r&#233;parent g&#233;n&#233;ralement en recousant les entailles ou en rajoutant de nouvelles pi&#232;ces de peau, ce qui donne aux armures en peau tr&#232;s utilis&#233;es leur apparence particuli&#232;re de patchwork.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure lamellaire en acier&quot; href=&quot;#Armure lamellaire en acier&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure lamellaire en acier*.&lt;/b&gt; L’armure lamellaire est un type d’armure constitu&#233; de petites plaques de diff&#233;rents m&#233;taux qui sont fix&#233;es en rang&#233;es parall&#232;les par une fine corde. Les plaques lamellaires peuvent &#234;tre faites de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Cuir-(Armure).html&quot; title=&quot;Armure lamellaire en cuir&quot;&gt;cuir laqu&#233;&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Corne-(Armure).html&quot; title=&quot;Armure lamellaire en corne&quot;&gt;corne&lt;/a&gt;, voire m&#234;me de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Pierre-(Armure).html&quot; title=&quot;Armure lamellaire en pierre&quot;&gt;pierre&lt;/a&gt;, mais les armures de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Fer-(Armure).html&quot; title=&quot;Armure lamellaire en fer&quot;&gt;fer&lt;/a&gt; et d’acier sont les plus courantes. L’armure lamellaire peut &#234;tre fa&#231;onn&#233;e en diff&#233;rentes formes, y compris en pi&#232;ces isol&#233;es telles que des cuirasses, des jambi&#232;res ou m&#234;me des vestes compl&#232;tes. Les propri&#233;t&#233;s des combinaisons et des pi&#232;ces sp&#233;cifiques de l’armure lamellaire sont d&#233;finies par leur mat&#233;riau.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure lamellaire en corne&quot; href=&quot;#Armure lamellaire en corne&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure lamellaire en corne*.&lt;/b&gt; L’armure lamellaire est un type d’armure constitu&#233; de petites plaques de diff&#233;rents m&#233;taux qui sont fix&#233;es en rang&#233;es parall&#232;les par une fine corde. Les plaques lamellaires peuvent &#234;tre faites de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Cuir-(Armure).html&quot; title=&quot;Armure lamellaire en cuir&quot;&gt;cuir laqu&#233;&lt;/a&gt;, de corne, voire m&#234;me de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Pierre-(Armure).html&quot; title=&quot;Armure lamellaire en pierre&quot;&gt;pierre&lt;/a&gt;, mais les armures de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Fer-(Armure).html&quot; title=&quot;Armure lamellaire en fer&quot;&gt;fer&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Acier-(Armure).html&quot; title=&quot;Armure lamellaire en acier&quot;&gt;acier&lt;/a&gt; sont les plus courantes. L’armure lamellaire peut &#234;tre fa&#231;onn&#233;e en diff&#233;rentes formes, y compris en pi&#232;ces isol&#233;es telles que des cuirasses, des jambi&#232;res ou m&#234;me des vestes compl&#232;tes. Les propri&#233;t&#233;s des combinaisons et des pi&#232;ces sp&#233;cifiques de l’armure lamellaire sont d&#233;finies par leur mat&#233;riau.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cotte de mailles&quot; href=&quot;#Cotte de mailles&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cotte de mailles.&lt;/b&gt; Contrairement &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Chemise-De-Mailles-(Armure).html&quot; title=&quot;Chemise de mailles&quot;&gt;chemise de mailles&lt;/a&gt;, qui ne couvre que la poitrine, la cotte de mailles prot&#232;ge son propri&#233;taire avec un r&#233;seau complet de maillons recouvrant le torse et les bras et descendant en-dessous de la taille. De multiples pi&#232;ces interconnect&#233;es offrent une protection suppl&#233;mentaire pour les zones vitales. L’armure inclut des &lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-(Arme).html&quot; title=&quot;Gantelet&quot;&gt;gantelets&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cuirasse&quot; href=&quot;#Cuirasse&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cuirasse.&lt;/b&gt; La cuirasse prot&#232;ge le torse du porteur d’une unique pi&#232;ce de m&#233;tal sculpt&#233;, similaire &#224; la pi&#232;ce principale d’un &lt;a class=&quot;pagelink&quot; href=&quot;Harnois-(Armure).html&quot; title=&quot;Harnois&quot;&gt;harnois&lt;/a&gt;. Malgr&#233; sa solidit&#233;, son manque de flexibilit&#233; et son dos ouvert en font une armure inf&#233;rieure aux armures de m&#233;tal compl&#232;tes mais elle constitue quand m&#234;me une am&#233;lioration par rapport &#224; la plupart des armures non-m&#233;talliques.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Cuirasse agile&quot; href=&quot;#Cuirasse agile&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cuirasse agile.&lt;/b&gt; Cette cuirasse est sp&#233;cialement fabriqu&#233;e de mani&#232;re &#224; donner plus d’aisance dans certaines activit&#233;s physiques. Le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Malusarmure.html&quot; title=&quot;malus d&amp;#39;armure&quot;&gt;malus d’armure&lt;/a&gt; aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; et aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour sauter n’est que de -1 (les versions &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; et en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html#MITHRAL&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;mithral&lt;/a&gt; de cette armure r&#233;duisent ce malus ainsi que le malus normal).&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Do-maru&quot; href=&quot;#Do-maru&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Do-maru*.&lt;/b&gt; Le do-maru, qui est la plus l&#233;g&#232;re des armures g&#233;n&#233;ralement pris&#233;e par les &lt;a class=&quot;pagelink&quot; href=&quot;Samoura&#239;.html&quot; title=&quot;Le samoura&#239;&quot;&gt;samoura&#239;s&lt;/a&gt;, enveloppe le corps du porteur comme une veste courte renforc&#233;e. Il se compose essentiellement de lamelles et n’a pas de manches ou de plastron solide, laissant les &#233;paules et le haut du corps quelque peu expos&#233;s mais donnant au porteur plus de souplesse que la plupart des armures lourdes.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Kikko&quot; href=&quot;#Kikko&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Kikko*.&lt;/b&gt; Le kikko est fait de plaques hexagonales en fer intelligemment dispos&#233;es et cousues au v&#234;tement, donnant ainsi au porteur une plus grande souplesse que celle qu’autorisent les nombreuses armures offrant une d&#233;fense similaire. On peut laisser les plaques visibles ou les cacher sous un v&#234;tement.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Veste renforc&#233;e&quot; href=&quot;#Veste renforc&#233;e&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Veste renforc&#233;e.&lt;/b&gt; Cette veste en cuir rembourr&#233; est renforc&#233;e de plaques de m&#233;tal cousues dans la doublure. La veste renforc&#233;e est plus encombrante qu’une armure l&#233;g&#232;re mais moins efficace que la plupart des armures interm&#233;diaires. En revanche, on peut l’enfiler ou la retirer par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Mouvement.html&quot; title=&quot;Action de mouvement&quot;&gt;action de mouvement&lt;/a&gt; (il n’y a pas d’option d’ &#171; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures.html#ENFILEROTER&quot; title=&quot;Caract&#233;ristiques des armures&quot;&gt;enfilage &#224; la h&#226;te&lt;/a&gt; &#187; pour les vestes renforc&#233;es). Si elle est port&#233;e par-dessus une autre armure, utilisez le meilleur bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et la pire valeur de toutes les autres cat&#233;gories. La veste renforc&#233;e n’a aucun effet si elle est port&#233;e avec une armure lourde. Les seuls effets magiques qui s’appliquent sont ceux des armures, des v&#234;tements ou des objets port&#233;s par-dessus.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Armures lourdes&lt;a class=&quot;headeranchor&quot; id=&quot;Armures_lourdes_2&quot; href=&quot;#Armures_lourdes_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.La Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea World Guide/La Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISWG.gif&quot; style=&quot;opacity: 0.7&quot;/&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure de L&#233;gionnaire infernal&quot; href=&quot;#Armure de L&#233;gionnaire infernal&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure de L&#233;gionnaire infernal.&lt;/b&gt; Ces armures reconnaissables sont semblables &#224; des &lt;a class=&quot;pagelink&quot; href=&quot;Harnois-(Armure).html&quot; title=&quot;Harnois&quot;&gt;harnois&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; qui offrent des avantages suppl&#233;mentaires &#224; leur propri&#233;taire s’il fait partie des &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Infernal.html&quot; title=&quot;L&#233;gionnaire infernal&quot;&gt;L&#233;gionnaires infernaux&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure de plaques&quot; href=&quot;#Armure de plaques&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure de plaques.&lt;/b&gt; L’armure de plaques combine des &#233;l&#233;ments du &lt;a class=&quot;pagelink&quot; href=&quot;Harnois-(Armure).html&quot; title=&quot;Harnois&quot;&gt;harnois&lt;/a&gt; et de la &lt;a class=&quot;pagelink&quot; href=&quot;Cotte-De-Mailles-(Armure).html&quot; title=&quot;Cotte de mailles&quot;&gt;cotte de mailles&lt;/a&gt;, int&#233;grant plusieurs grandes plaques de m&#233;tal sculpt&#233; et une armature de mailles. Si cette armure prot&#232;ge les zones vitales de plusieurs couches d’armure, elle n’est pas sculpt&#233;e en fonction de la carrure de l’individu, r&#233;duisant davantage la mobilit&#233; du porteur qu’un harnois complet. Les armures de plaques incluent des &lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-(Arme).html&quot; title=&quot;Gantelet&quot;&gt;gantelets&lt;/a&gt; et un casque.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure de plaques agile&quot; href=&quot;#Armure de plaques agile&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure de plaques agile.&lt;/b&gt; Cette &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Plaques-(Armure).html&quot; title=&quot;Armure de plaques&quot;&gt;armure de plaques&lt;/a&gt; est fabriqu&#233;e dans un style sp&#233;cialement con&#231;u pour donner plus d’aisance lors de certaines activit&#233;s physiques. Le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Malusarmure.html&quot; title=&quot;malus d&amp;#39;armure&quot;&gt;malus d’armure&lt;/a&gt; aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt; et aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html#SAUTER&quot; title=&quot;Acrobaties&quot;&gt;saut&lt;/a&gt; n’est que de -4 (les versions &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures#Armuresmaitre.html&quot; title=&quot;armure de ma&#238;tre&quot;&gt;de ma&#238;tre&lt;/a&gt; et en &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html#MITHRAL&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;mithral&lt;/a&gt; de cette armure r&#233;duisent ce malus et le malus normal). En outre, contrairement &#224; la plupart des armures lourdes, le porteur peut quand m&#234;me &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Complexes#Courir.html&quot; title=&quot;courir&quot;&gt;courir&lt;/a&gt; &#224; quatre fois sa vitesse au lieu de trois fois sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure lamellaire en fer&quot; href=&quot;#Armure lamellaire en fer&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure lamellaire en fer*.&lt;/b&gt; L’armure lamellaire est un type d’armure constitu&#233; de petites plaques de diff&#233;rents m&#233;taux qui sont fix&#233;es en rang&#233;es parall&#232;les par une fine corde. Les plaques lamellaires peuvent &#234;tre faites de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Cuir-(Armure).html&quot; title=&quot;Armure lamellaire en cuir&quot;&gt;cuir laqu&#233;&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Corne-(Armure).html&quot; title=&quot;Armure lamellaire en corne&quot;&gt;corne&lt;/a&gt;, voire m&#234;me de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Pierre-(Armure).html&quot; title=&quot;Armure lamellaire en pierre&quot;&gt;pierre&lt;/a&gt;, mais les armures de fer et d’&lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Acier-(Armure).html&quot; title=&quot;Armure lamellaire en acier&quot;&gt;acier&lt;/a&gt; sont les plus courantes. L’armure lamellaire peut &#234;tre fa&#231;onn&#233;e en diff&#233;rentes formes, y compris en pi&#232;ces isol&#233;es telles que des cuirasses, des jambi&#232;res ou m&#234;me des vestes compl&#232;tes. Les propri&#233;t&#233;s des combinaisons et des pi&#232;ces sp&#233;cifiques de l’armure lamellaire sont d&#233;finies par leur mat&#233;riau.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Armure lamellaire en pierre&quot; href=&quot;#Armure lamellaire en pierre&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Armure lamellaire en pierre*.&lt;/b&gt; L’armure lamellaire est un type d’armure constitu&#233; de petites plaques de diff&#233;rents m&#233;taux qui sont fix&#233;es en rang&#233;es parall&#232;les par une fine corde. Les plaques lamellaires peuvent &#234;tre faites de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Cuir-(Armure).html&quot; title=&quot;Armure lamellaire en cuir&quot;&gt;cuir laqu&#233;&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Corne-(Armure).html&quot; title=&quot;Armure lamellaire en corne&quot;&gt;corne&lt;/a&gt;, voire m&#234;me de pierre, mais les armures de &lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Fer-(Armure).html&quot; title=&quot;Armure lamellaire en fer&quot;&gt;fer&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;Armure-Lamellaire-En-Acier-(Armure).html&quot; title=&quot;Armure lamellaire en acier&quot;&gt;acier&lt;/a&gt; sont les plus courantes. L’armure lamellaire peut &#234;tre fa&#231;onn&#233;e en diff&#233;rentes formes, y compris en pi&#232;ces isol&#233;es telles que des cuirasses, des jambi&#232;res ou m&#234;me des vestes compl&#232;tes. Les propri&#233;t&#233;s des combinaisons et des pi&#232;ces sp&#233;cifiques de l’armure lamellaire sont d&#233;finies par leur mat&#233;riau.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Clibanion&quot; href=&quot;#Clibanion&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Clibanion.&lt;/b&gt; Le clibanion est compos&#233; de bandes de m&#233;tal superpos&#233;es fix&#233;es sur une armature de cuir ou de tissu r&#233;sistant. Ces attelles sont plus grandes et plus r&#233;sistantes que celles qui composent l’armure d’&#233;cailles, am&#233;liorant la protection qu’elle offre au porteur, aux d&#233;pends de la flexibilit&#233;. Un clibanion s’accompagne de &lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-(Arme).html&quot; title=&quot;Gantelet&quot;&gt;gantelets&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Crevice&quot; href=&quot;#Crevice&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Crevice.&lt;/b&gt; La crevice est compos&#233;e de bandes de m&#233;tal superpos&#233;es et fix&#233;es sur un solide support de cuir et de cha&#238;nes. La taille des plaques de m&#233;tal, des bandes de m&#233;tal interconnect&#233;es et des couches de l’armure int&#233;rieure en font un moyen de d&#233;fense plus important que les armures similaires, telles que l’&lt;a class=&quot;pagelink&quot; href=&quot;Armure-D&#233;cailles-(Armure).html&quot; title=&quot;Armure d&amp;#39;&#233;cailles&quot;&gt;armure d’&#233;cailles&lt;/a&gt; ou le &lt;a class=&quot;pagelink&quot; href=&quot;Clibanion-(Armure).html&quot; title=&quot;Clibanion&quot;&gt;clibanion&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;50%&quot; style=&quot;vertical-align:top; border-left:solid 1px #002564; padding-left:10px&quot;&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Harnois&quot; href=&quot;#Harnois&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Harnois.&lt;/b&gt; Cette armure de m&#233;tal se compose de multiples plaques de m&#233;tal interconnect&#233;es et superpos&#233;es int&#233;grant les avantages de nombreux types d’armures inf&#233;rieures. Le harnois (ou &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Plaques-(Armure).html&quot; title=&quot;Armure de plaques&quot;&gt;armure de plaques&lt;/a&gt; compl&#232;te, comme on l’appelle souvent) inclut des &lt;a class=&quot;pagelink&quot; href=&quot;Gantelet-(Arme).html&quot; title=&quot;Gantelet&quot;&gt;gantelets&lt;/a&gt;, des bottes de cuir lourdes, un casque &#224; visi&#232;re et un &#233;pais rembourrage cousu sous l’armure. Chaque harnois doit &#234;tre sp&#233;cialement taill&#233; pour son porteur par un ma&#238;tre armurier, bien qu’il soit possible de r&#233;ajuster une armure r&#233;cup&#233;r&#233;e pour l’adapter &#224; son nouveau porteur, pour un prix allant de 200 &#224; 800 (2d4 &#215; 100) pi&#232;ces d’or.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Kusari gusoku&quot; href=&quot;#Kusari gusoku&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Kusari gusoku*.&lt;/b&gt; Le kusari gusoku ressemble &#224; l’armure &lt;a class=&quot;pagelink&quot; href=&quot;Tatami-Do-(Armure).html&quot; title=&quot;Tatami-do&quot;&gt;tatami-do&lt;/a&gt; mais le katabira (sorte de veste de mailles) se porte &#224; la place du plastron.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;O-yoro&#239;&quot; href=&quot;#O-yoro&#239;&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;O-yoro&#239;*.&lt;/b&gt; Exclusivement port&#233; par les &lt;a class=&quot;pagelink&quot; href=&quot;Samoura&#239;.html&quot; title=&quot;Le samoura&#239;&quot;&gt;samoura&#239;s&lt;/a&gt; de haut rang, l’o-yoro&#239; (ou &#171; grande armure &#187;) est une armure lourde de combat faite de divers composants suppl&#233;mentaires incluant des plaques et des lamelles. Chaque armure est taill&#233;e pour un individu particulier et porte la marque esth&#233;tique de son propri&#233;taire. Lors de la finition, l’armure est color&#233;e et scell&#233;e avec une derni&#232;re couche de laque. La pi&#232;ce ma&#238;tresse de l’o-yoro&#239; est une cuirasse se composant de deux parties : un renforcement ind&#233;pendant pour le flanc droit, que l’on appelle un waidate, et un &lt;a class=&quot;pagelink&quot; href=&quot;Kikko-(Armure).html&quot; title=&quot;Kikko&quot;&gt;kikko&lt;/a&gt;. La partie sup&#233;rieure du waidate se compose d’une plaque de fer recouverte de cuir. Les bretelles de cuir de la cuirasse (les watagami) sont &#233;galement renforc&#233;es de plaques de m&#233;tal. Un certain nombre de pi&#232;ces suppl&#233;mentaires sont fix&#233;es &#224; la cuirasse, dont de larges &#233;pauli&#232;res lamellaires, une manche de kikko pour le bras prot&#233;g&#233;, des jambi&#232;res de fer laqu&#233; port&#233;es par-dessus des collants de soie matelass&#233;s et une protection du bassin. L’&#233;l&#233;ment caract&#233;ristique de chaque combinaison d’armure est un casque kabuto et le masque ho-ate qui l’accompagne. Il est possible de fabriquer les masques ho-ate en cuir renforc&#233; ou en m&#233;tal. Ils repr&#233;sentent un visage effrayant comme celui d’un &lt;a class=&quot;pagelink&quot; href=&quot;Oni.html&quot; title=&quot;Les onis&quot;&gt;oni&lt;/a&gt;], d’un &lt;a class=&quot;pagelink&quot; href=&quot;Dragon.html&quot; title=&quot;Les dragons v&#233;ritables&quot;&gt;dragon&lt;/a&gt; ou d’autres cr&#233;atures mythologiques.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Plate de pierre&quot; href=&quot;#Plate de pierre&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Plate de pierre.&lt;/b&gt; &lt;div style=&quot;float:right; padding: 0 0 8px 8px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; width:250px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;Dans l&#39;&lt;u&gt;Art de la guerre&lt;/u&gt;, cet objet est aussi appel&#233; &quot;manteau de pierre&quot;.&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:30px; cursor:pointer&quot; src=&quot;/images/pathfinder/wiki/ibase.png&quot; title=&quot;Cliquez pour afficher/cacher une d&#233;sambigu&#239;sation (homonymes, redirections, etc...)&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
