  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;Cette armure est fabriqu&#233;e par les forgerons nains &#224; partir de plaques de basalte alchimiquement renforc&#233;es. La plate de pierre est une armure lourde et encombrante mais elle offre une protection exceptionnelle &#224; son porteur. Elle est principalement utilis&#233;e par les &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druides&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;nains&lt;/a&gt; qui ne peuvent pas porter d’armure en m&#233;tal.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.La Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea World Guide/La Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISWG.gif&quot; style=&quot;opacity: 0.7&quot;/&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Plate flexible&quot; href=&quot;#Plate flexible&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Plate flexible.&lt;/b&gt; Cette armure lourde est similaire &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Harnois-(Armure).html&quot; title=&quot;Harnois&quot;&gt;harnois&lt;/a&gt; mais elle est un peu plus l&#233;g&#232;re et sacrifie une part de protection pour b&#233;n&#233;ficier d’une meilleure flexibilit&#233; et d’une plus grande mobilit&#233;.&lt;br /&gt;&lt;br /&gt;&lt;br style=&quot;clear:right&quot; /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armes et &#233;quipement (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Equipment/Armes et &#201;quipement&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAE.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Tatami-do&quot; href=&quot;#Tatami-do&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Tatami-do*.&lt;/b&gt; Port&#233; par les &lt;a class=&quot;pagelink&quot; href=&quot;Samoura&#239;.html&quot; title=&quot;Le samoura&#239;&quot;&gt;samoura&#239;s&lt;/a&gt; comme une alternative plus l&#233;g&#232;re &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;O-Yoro&#239;-(Armure).html&quot; title=&quot;O-yoro&#239;&quot;&gt;o-yoro&#239;&lt;/a&gt;, le tatami-do est une armure flexible int&#233;grale combinant les lamelles m&#233;talliques et les composantes du &lt;a class=&quot;pagelink&quot; href=&quot;Kikko-(Armure).html&quot; title=&quot;Kikko&quot;&gt;kikko&lt;/a&gt; pour faire une combinaison de mailles sur une armature de tissu. Il inclut g&#233;n&#233;ralement un casque kabuto escamotable ou un capuchon renforc&#233;, ainsi que des protections pour les bras, des &#233;pauli&#232;res et des protections pour les cuisses.&lt;br /&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Boucliers&lt;a class=&quot;headeranchor&quot; id=&quot;Boucliers_3&quot; href=&quot;#Boucliers_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;50%&quot; style=&quot;padding-right:10px&quot;&gt;
